$ErrorActionPreference="Stop";$workspace=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path;$zip=(Resolve-Path (Join-Path $workspace "artifacts\Lumina-0.3.0-portable-windows-x64.zip")).Path;$extract=Join-Path $env:TEMP ("Lumina-03-Smoke-"+[guid]::NewGuid().ToString("N"));Expand-Archive -LiteralPath $zip -DestinationPath $extract;$root=Get-ChildItem -LiteralPath $extract -Directory|Select-Object -First 1;$manifest=Get-Content (Join-Path $root.FullName "MANIFEST.json") -Raw|ConvertFrom-Json;foreach($entry in $manifest){$path=Join-Path $root.FullName $entry.path.Replace("/","\");if(-not(Test-Path -LiteralPath $path)){throw "Ausente: $($entry.path)"};if((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()-ne $entry.sha256){throw "Hash inválido: $($entry.path)"}}
$data=Join-Path $extract "local-data";New-Item -ItemType Directory $data|Out-Null;$info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=Join-Path $root.FullName "Lumina.exe";$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.Environment["LOCALAPPDATA"]=$data;$info.Environment["Path"]="$env:SystemRoot\System32;$env:SystemRoot";$app=[Diagnostics.Process]::Start($info);Start-Sleep 5;if($app.HasExited){throw "Aplicativo encerrou: $($app.ExitCode)"};$app.Kill();$app.WaitForExit();$toolsBundled=Test-Path(Join-Path $root.FullName "tools\ffmpeg.exe");$sha=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLowerInvariant();$resolved=(Resolve-Path $extract).Path;$temp=(Resolve-Path $env:TEMP).Path;if(-not $resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)){throw "Limpeza fora de TEMP recusada"};Remove-Item -LiteralPath $resolved -Recurse -Force;[pscustomobject]@{ManifestEntries=$manifest.Count;StayedRunning=$true;ToolsBundled=$toolsBundled;Sha256=$sha}
